pawn() ->\n    Self = self(),\n    Child = erpc:call(node(),erlang,self,[],#{always_spawn=>true}),\n    true = is_pid(Child), false = (Child =:= Self),\n    ok.\n\nuser_system_limit() -> error(system_limit).\n\nbadarg(F) ->\n    try F() of _ -> error(unexpected_return)\n    catch error:badarg -> ok end.\n\nrun() -> always_spawn().\n";
    internal const string RpcFiniteUsesChild = "-module(oracle_connected_dependency).\n-export([run/0]).\nrun() ->\n    Self=self(),Child=erpc:call(node(),erlang,self,[],1000),true=is_pid(Child),false=(Child=:=Self),ok.\n";
    internal const string ApplyInvalidFunctionPrecedesCap = "-module(apply_invalid_function_precedes_cap).\n-export([run/0]).\nrun() ->\n    Args = args(1024, []),\n    try erlang:apply(missing_apply_boundary_target, 42, Args) of\n        Value -> {unexpected_return, Value}\n    catch\n        error:badarg -> ok;\n        Class:Reason -> {unexpected_exception, Class, Reason}\n    end.\nargs(0, Tail) -> Tail;\nargs(N, Tail) -> args(N - 1, [item | Tail]).\n";
